CREATE TABLE bcf_document(id INTEGER PRIMARY KEY, schema_identity TEXT NOT NULL, version TEXT NOT NULL);
CREATE TABLE bcf_topic(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES bcf_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), guid TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL, priority TEXT NOT NULL, creation_date TEXT NOT NULL, creation_author TEXT NOT NULL);
CREATE TABLE bcf_topic_label(id INTEGER PRIMARY KEY, topic_id INTEGER NOT NULL REFERENCES bcf_topic(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), label TEXT NOT NULL);
CREATE TABLE bcf_comment(id INTEGER PRIMARY KEY, topic_id INTEGER NOT NULL REFERENCES bcf_topic(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), guid TEXT NOT NULL, date TEXT NOT NULL, author TEXT NOT NULL, text TEXT NOT NULL, viewpoint_reference TEXT);
CREATE TABLE bcf_viewpoint(id INTEGER PRIMARY KEY, topic_id INTEGER NOT NULL REFERENCES bcf_topic(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), guid TEXT NOT NULL);
CREATE TABLE bcf_camera(id INTEGER PRIMARY KEY REFERENCES bcf_viewpoint(id), kind TEXT NOT NULL CHECK(kind IN ('perspective','orthogonal')), view_point_x REAL, view_point_y REAL, view_point_z REAL, direction_x REAL, direction_y REAL, direction_z REAL, up_vector_x REAL, up_vector_y REAL, up_vector_z REAL, view_point_x_ieee754_bits INTEGER NOT NULL, view_point_x_ieee754_class TEXT NOT NULL, view_point_y_ieee754_bits INTEGER NOT NULL, view_point_y_ieee754_class TEXT NOT NULL, view_point_z_ieee754_bits INTEGER NOT NULL, view_point_z_ieee754_class TEXT NOT NULL, direction_x_ieee754_bits INTEGER NOT NULL, direction_x_ieee754_class TEXT NOT NULL, direction_y_ieee754_bits INTEGER NOT NULL, direction_y_ieee754_class TEXT NOT NULL, direction_z_ieee754_bits INTEGER NOT NULL, direction_z_ieee754_class TEXT NOT NULL, up_vector_x_ieee754_bits INTEGER NOT NULL, up_vector_x_ieee754_class TEXT NOT NULL, up_vector_y_ieee754_bits INTEGER NOT NULL, up_vector_y_ieee754_class TEXT NOT NULL, up_vector_z_ieee754_bits INTEGER NOT NULL, up_vector_z_ieee754_class TEXT NOT NULL);
CREATE TABLE bcf_perspective_camera(id INTEGER PRIMARY KEY REFERENCES bcf_camera(id), field_of_view REAL, field_of_view_ieee754_bits INTEGER NOT NULL, field_of_view_ieee754_class TEXT NOT NULL);
CREATE TABLE bcf_orthogonal_camera(id INTEGER PRIMARY KEY REFERENCES bcf_camera(id), view_to_world_scale REAL, view_to_world_scale_ieee754_bits INTEGER NOT NULL, view_to_world_scale_ieee754_class TEXT NOT NULL);
CREATE TABLE bcf_components(id INTEGER PRIMARY KEY REFERENCES bcf_viewpoint(id), default_visibility INTEGER NOT NULL CHECK(default_visibility IN (0,1)));
CREATE TABLE bcf_selection(id INTEGER PRIMARY KEY, components_id INTEGER NOT NULL REFERENCES bcf_components(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), component_guid TEXT NOT NULL);
CREATE TABLE bcf_visibility_exception(id INTEGER PRIMARY KEY, components_id INTEGER NOT NULL REFERENCES bcf_components(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), component_guid TEXT NOT NULL);
CREATE TABLE bcf_coloring(id INTEGER PRIMARY KEY, components_id INTEGER NOT NULL REFERENCES bcf_components(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), color TEXT NOT NULL);
CREATE TABLE bcf_coloring_component(id INTEGER PRIMARY KEY, coloring_id INTEGER NOT NULL REFERENCES bcf_coloring(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), component_guid TEXT NOT NULL);
CREATE TABLE bcf_snapshot_image(id INTEGER PRIMARY KEY REFERENCES bcf_viewpoint(id), image_bytes BLOB NOT NULL);
CREATE TABLE bcf_raw_part(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES bcf_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), name TEXT NOT NULL, part_bytes BLOB NOT NULL);
